const binary = item.binary || {};

function deepFind(obj, key, depth = 0) {
  if (depth > 8 || obj == null) return '';

  if (typeof obj === 'string') {
    try {
      const parsed = JSON.parse(obj);
      return deepFind(parsed, key, depth + 1);
    } catch {
      return '';
    }
  }

  if (typeof obj !== 'object') return '';

  if (
    Object.prototype.hasOwnProperty.call(obj, key) &&
    typeof obj[key] === 'string' &&
    obj[key].trim().length > 0
  ) {
    return obj[key].trim();
  }

  for (const k of Object.keys(obj)) {
    if (k === 'headers') continue;
    const found = deepFind(obj[k], key, depth + 1);
    if (found) return found;
  }

  return '';
}

const query = deepFind(raw, 'query');
const audioBase64 = deepFind(raw, 'audio');

const binaryKey = Object.keys(binary)[0] || '';
const hasBinaryAudio = !!binaryKey;

const hasAudio = hasBinaryAudio || audioBase64.length > 0;
const hasText = query.length > 0;

if (!hasAudio && !hasText) {
  throw new Error(
    'Request must include either a "query" field or an audio file. ' +
    'Available JSON keys: ' + JSON.stringify(Object.keys(raw)) +
    ' | Binary keys: ' + JSON.stringify(Object.keys(binary))
  );
}

return [
  {
    json: {
      type: hasAudio ? 'audio' : 'text',
      hasAudio,
      hasText,
      query,
      audioBase64,
      binaryProperty: binaryKey
    },
    binary
  }
];

const item = $input.first();

if (item.binary && Object.keys(item.binary).length > 0) {
  return [item];
}

if (item.json.audioBase64) {
  const buffer = Buffer.from(item.json.audioBase64, 'base64');

  return [{
    json: item.json,
    binary: {
      data: await this.helpers.prepareBinaryData(
        buffer,
        'audio.webm',
        'audio/webm'
      )
    }
  }];
}

throw new Error("No binary audio or base64 audio found.");

const item = $input.first();

let finalQuery = '';

if (typeof item.json.text === 'string' && item.json.text.trim().length > 0) {
  finalQuery = item.json.text.trim();
} else if (typeof item.json.query === 'string' && item.json.query.trim().length > 0) {
  finalQuery = item.json.query.trim();
}

if (!finalQuery) {
  throw new Error('Could not resolve a search query from the provided input.');
}

const sourceType = $('Detect Input Type1').item.json.type === 'audio' ? 'speech-to-text transcript (audio)' : 'direct search box text';

return [{ json: { query: finalQuery, sourceType, inputType: $('Detect Input Type1').item.json.type } }];

