const searchTerm = query.trim();

if (!searchTerm) return "No search term provided";

const orFilter = `or=(Format.ilike.*${searchTerm}*,City.ilike.*${searchTerm}*,State.ilike.*${searchTerm}*,Calls.ilike.*${searchTerm}*,Slogan.ilike.*${searchTerm}*,Phone.ilike.*${searchTerm}*)`;

const url = `https://kwwqfcodcbzbyawnlyxe.supabase.co/rest/v1/Recall_Search?${orFilter}&select=*&limit=500`;

try {

  const response = await this.helpers.httpRequest({

    method: 'GET',

    url: url,

    headers: {

      'apikey': 'put supabase api key',

      'Authorization': 'Bearer put supabase api key',

      'Content-Type': 'application/json'

    },

    json: true

  });

  const data = response;

  if (!data || data.length === 0) return "No stations found matching your search.";

  // Helper: check if a value looks valid (not empty, not garbage)

  const isValid = (val, type) => {

    if (val === null || val === undefined) return false;

    const str = String(val).trim();

    if (str === '' || str.toUpperCase() === 'NULL') return false;

    if (type === 'phone' && !/\d{3}[-.]?\d{3}[-.]?\d{4}/.test(str)) return false;

    if (type === 'calls' && /kw$/i.test(str)) return false; // power rating, not a call sign

    if (type === 'city' && /^https?:\/\//i.test(str)) return false; // URL, not a city

    return true;

  };

  const lines = data.map(row => {

    const parts = [];

    if (isValid(row['Calls'], 'calls')) parts.push(row['Calls']);

    if (isValid(row['Format'])) parts.push(row['Format']);

    if (isValid(row['City'], 'city')) parts.push(row['City']);

    if (isValid(row['State'])) parts.push(row['State']);

    if (isValid(row['Phone'], 'phone')) parts.push(row['Phone']);

    return parts.length > 0 ? parts.join(', ') : null;

  }).filter(line => line !== null);

  if (lines.length === 0) return "Found matching records, but the data was incomplete or invalid.";

  return `Found ${lines.length} matching station(s):\n${lines.join('\n')}`;

} catch (error) {

  return `Error: ${error.message}`;

}

const item = $input.first();
let rawSummary = (item.json.summary || '').trim();

// Convert literal "\n" (backslash + n text) into real newline characters
rawSummary = rawSummary.replace(/\\n/g, '\n');

const query = $('Normalize Query1').item.json.query;

// Split into lines, remove empty lines
let lines = rawSummary
  .split('\n')
  .map(l => l.trim())
  .filter(l => l.length > 0);

// Detect "no results" case
const firstLine = lines[0] || '';
const isNoResults = !/^found\s+\d+/i.test(firstLine);

let results = [];
let count = 0;

if (!isNoResults) {
  // Remove the header line ("Found 9 matching station(s):")
  const dataLines = lines.slice(1);

  results = dataLines.map(line => {
    const parts = line.split(',').map(p => p.trim()).filter(p => p.length > 0);

    return {
      raw: line,
      calls: parts[0] || null,
      format: parts[1] || null,
      city: parts[2] || null,
      state: parts[3] || null,
      phone: parts[4] || null
    };
  });

  count = results.length;
}

return [{
  json: {
    success: true,
    query,
    matched: count > 0,
    count,
    results
  }
}];
